    return lines


def case_item(case: dict[str, Any]) -> dict[str, Any]:
    request = case["request"]
    headers = [{"key": str(k), "value": str(v), "type": "text"} for k, v in request.get("headers", {}).items()]
    body = request.get("body")
    request_json: dict[str, Any] = {
        "method": request["method"],
        "header": headers,
        "url": build_url(request["path"], request.get("query", [])),
        "description": f"Prerequisite: {case['prerequisite']}\nOracle: {case['oracle']}",
    }
    if "raw_body" in request:
        if not any(h["key"].lower() == "content-type" for h in headers):
            headers.append({"key": "Content-Type", "value": "application/json", "type": "text"})
        request_json["body"] = {
            "mode": "raw",
            "raw": request["raw_body"],
            "options": {"raw": {"language": "json"}},
        }
    elif body is not None:
        if not any(h["key"].lower() == "content-type" for h in headers):
            headers.append({"key": "Content-Type", "value": "application/json", "type": "text"})
        request_json["body"] = {
            "mode": "raw",
            "raw": json.dumps(body, ensure_ascii=False, indent=2),
            "options": {"raw": {"language": "json"}},
        }
    events = []
    pre = setup_script(case)
    if pre:
        events.append(script_event("prerequest", pre))
    events.append(script_event("test", test_script(case)))
    return {
        "name": f"{case['id']} - {case.get('title', 'Unnamed case')}",
        "request": request_json,
        "event": events,
    }


def build_collection(data: dict[str, Any]) -> dict[str, Any]:
    meta = data["meta"]
    prerequest = [
        "const studentId = pm.variables.replaceIn('{{student_id}}');",
        "if (!studentId || studentId === '{{student_id}}') { throw new Error('student_id is required'); }",
        "pm.request.headers.upsert({ key: 'X-Student-Id', value: studentId });",
        "console.log('X-Student-Id:', studentId);",
    ]
    return {
        "info": {
            "name": f"{meta['student_id']} HW06 EShop API Tests",
            "description": "Generated from the reviewed HW06 catalog. Expected results come from the EShop specification.",
            "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json",
        },
        "variable": [
            {"key": "base_url", "value": meta["base_url"]},
            {"key": "student_id", "value": meta["student_id"]},
        ],
        "event": [script_event("prerequest", prerequest)],
        "item": [
            {
                "name": f"Pool {api['pool']} - {api['api_id']} - {api['feature']}",
                "description": api["contract"],
                "item": [case_item(case) for case in api["cases"] if case.get("audit", {}).get("verdict") != "INVALID" and case.get("automation") != "MANUAL"],
            }
            for api in data["apis"]
        ],
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("catalog", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--check", action="store_true", help="validate generated structure without writing")
    parser.add_argument("--allow-partial", action="store_true")
    args = parser.parse_args()
    try:
        data = load_catalog(args.catalog)
        errors = validate_catalog(data, args.allow_partial)
        if errors:
            print(json.dumps({"built": False, "errors": errors}, ensure_ascii=False, indent=2))
            return 1
        collection = build_collection(data)
        encoded = json.dumps(collection, ensure_ascii=False, indent=2) + "\n"
        json.loads(encoded)
        if not args.check:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(encoded, encoding="utf-8")
        print(json.dumps({"built": True, "items": sum(len(folder["item"]) for folder in collection["item"]), "output": None if args.check else str(args.output)}, ensure_ascii=False, indent=2))
        return 0
    except (OSError, ValueError, json.JSONDecodeError, KeyError) as exc:
        print(json.dumps({"built": False, "errors": [str(exc)]}, ensure_ascii=False, indent=2))
        return 2


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""Unit tests for the EShop catalog validator and Postman builder."""

from __future__ import annotations

import unittest

from build_postman_collection import build_collection
from validate_catalog import validate_catalog


def full_catalog():
    apis = []
    sec_ids = [f"SEC-0{i}" for i in range(1, 8)]
    for pool in "ABC":
        ec_id = f"{pool}-EC-VALID"
        cases = []
        for index in range(1, 41):
            origin = "AI" if index <= 35 else "STUDENT"
            cases.append({
                "id": f"{pool}-{'AI' if origin == 'AI' else 'STU'}-{index:03d}",
                "title": "generated fixture",
                "origin": origin,
                "missed_by_ai": "Cross-pass fixture" if origin == "STUDENT" else "",
                "audit": {"verdict": "VALID", "reason": "Matches fixture contract", "fix": "None"},
                "coverage": ["domain", "state", "security", "schema"] if index == 1 else ["domain"],
                "equivalence_classes": [ec_id],
                "security_requirements": sec_ids if pool == "A" and index == 1 else [],
                "prerequisite": "Seeded fixture",
                "oracle": "Fixture contract",
                "request": {"method": "GET", "path": "/api/fixture", "headers": {}, "query": []},
                "expected": {
                    "status": [200],
                    **({"content_type": "application/json", "json_schema": {"type": "object"}} if index == 1 else {}),
                },
            })
        apis.append({
            "api_id": f"API-{pool}",
            "pool": pool,
            "feature": "Fixture",
            "method": "GET",
            "path": "/api/fixture",
            "contract": "Fixture contract",
            "equivalence_classes": [{"id": ec_id, "variable": "fixture", "class": "valid", "validity": "VALID"}],
            "cases": cases,
        })
    return {
        "meta": {
            "student_id": "23127272",
            "base_url": "http://localhost:3000",
            "sut_commit": "85af3ba875c88283615e22cb108f13e2fccaf0e9",
        },
        "apis": apis,
    }


class SkillScriptTests(unittest.TestCase):
    def test_full_catalog_passes(self):
        self.assertEqual(validate_catalog(full_catalog()), [])

    def test_missing_ai_cases_fails(self):
        data = full_catalog()
        data["apis"][0]["cases"] = data["apis"][0]["cases"][10:]
        errors = validate_catalog(data)
        self.assertTrue(any("at least 35 AI cases" in error for error in errors))

    def test_collection_has_header_script_and_120_items(self):
        collection = build_collection(full_catalog())
        script = "\n".join(collection["event"][0]["script"]["exec"])
        self.assertIn("X-Student-Id", script)
        self.assertEqual(sum(len(folder["item"]) for folder in collection["item"]), 120)


if __name__ == "__main__":
    unittest.main()

